const orders = {
  "1001": "Доставлен 28 октября.",
  "1042": "Отправлен 2 ноября, трек-номер RU123456789, доставка ожидается 6 ноября.",
  "1077": "Собирается на складе, отправка 5 ноября.",
  "1100": "Отменён по просьбе покупателя, деньги возвращены 1 ноября.",
  "1123": "Ожидает оплаты; заказ отправим после оплаты."
};
const id = String(query.order_number || "").replace(/\D/g, "");
return orders[id] ? `Заказ ${id}: ${orders[id]}` : `Заказ ${id} не найден.`;

const policies = [
  ["доставка доставку стоимость бесплатно курьер сроки", "Доставка курьером 1–3 дня, стоимость 299 ₽; бесплатно для заказов от 2000 ₽."],
  ["возврат вернуть обмен книга понравилась электронная", "Бумажную книгу можно вернуть в течение 14 дней, если на ней нет следов использования. Электронные книги вернуть нельзя."],
  ["оплата оплатить карта сбп наличные рассрочка кредит", "Оплата картой, через СБП или наличными курьеру. Рассрочки и кредита нет."],
  ["сертификат подарочный подарок номинал срок", "Подарочные сертификаты номиналом 1000, 3000 и 5000 ₽, действуют 1 год с даты покупки."],
  ["бонусы бонус баллы кешбэк начисляют списать", "За покупку начисляется 5% бонусами; бонусами можно оплатить до 30% суммы заказа."],
  ["самовывоз забрать пункт адрес часы работы", "Пункт самовывоза: ул. Ленина, 10, ежедневно с 10:00 до 21:00."]
];
const words = String(query.query || "").toLowerCase().replace(/ё/g, "е").split(/[^a-zа-я0-9]+/).filter(w => w.length > 2);
const scored = policies.map(([keys, text]) => [words.filter(w => keys.includes(w.slice(0, 5))).length, text]);
const found = scored.filter(([s]) => s > 0).sort((a, b) => b[0] - a[0]).map(([, t]) => t);
return found.length ? found.join("\n") : "В правилах магазина нет информации по этому вопросу.";
